CREATE SCHEMA IF NOT EXISTS presus;
create table presus.actas (fecha_generacion date not null, firmada boolean not null, firmada_presidente boolean not null, firmada_tutor boolean not null, firmada_vocal1 boolean not null, firmada_vocal2 boolean not null, fecha_firma_presidente timestamp(6), fecha_firma_tutor timestamp(6), fecha_firma_vocal1 timestamp(6), fecha_firma_vocal2 timestamp(6), id bigint generated by default as identity, solicitud_id bigint not null unique, archivo_pdf varchar(255), observaciones_acta TEXT, primary key (id));
create table presus.anteproyectos (fecha_envio date, id bigint generated by default as identity, solicitud_id bigint unique, tamano_bytes bigint, estado_id smallint not null default 1, estado varchar(30), sha256_hash varchar(64), archivo_pdf varchar(255), observaciones TEXT, primary key (id));
create table presus.areas_tematicas (id integer generated by default as identity, linea_investigacion_id integer not null, nombre varchar(150) not null, descripcion TEXT, primary key (id));
create table presus.bloques_horarios (hora_fin time(6) not null, hora_inicio time(6) not null, id integer generated by default as identity, jornada_id smallint not null, nombre varchar(60) not null, primary key (id));
create table presus.carreras (facultad_id integer not null, id integer generated by default as identity, codigo varchar(20) not null unique, modalidad_estudio varchar(40), nombre varchar(150) not null, primary key (id));
create table presus.convocatorias_titulacion (activa boolean not null, fecha_fin date not null, fecha_inicio date not null, id integer generated by default as identity, periodo_academico_id integer not null, codigo varchar(30) not null unique, nombre varchar(150) not null, primary key (id));
create table presus.criterios_rubrica (orden integer not null, ponderacion float(53) not null, id bigint generated by default as identity, rubrica_id bigint not null, nombre varchar(100) not null, descripcion TEXT, primary key (id));
create table presus.cronograma (bloque_id integer, convocatoria_id integer not null, duracion_min integer not null, estado_id smallint not null, estado varchar(30) not null default 'PROGRAMADO', numero_intento smallint not null, creado_en timestamp(6) not null, fecha_inicio timestamp(6) not null, id bigint generated by default as identity, sala_id bigint not null, solicitud_id bigint not null, primary key (id));
create table presus.disponibilidad_sala (bloque_id integer not null, disponible boolean not null, fecha date not null, id bigint generated by default as identity, sala_id bigint not null, motivo varchar(200), primary key (id));
create table presus.docente (carga_horaria_semanal integer not null, disponible boolean not null, facultad_id integer, creado_en timestamp(6) not null, id bigint generated by default as identity, usuario_id bigint not null unique, area_especialidad varchar(180), primary key (id));
create table presus.estados_cronograma (id smallint not null, codigo varchar(30) not null unique, nombre varchar(80) not null, primary key (id));
create table presus.estados_proceso (id smallint not null, codigo varchar(30) not null unique, nombre varchar(80) not null, primary key (id));
create table presus.estados_solicitud (id smallint not null, orden smallint not null, codigo varchar(30) not null unique, nombre varchar(80) not null, primary key (id));
create table presus.estudiante (carrera_id integer not null, periodo_ingreso_id integer, semestre_actual smallint not null, creado_en timestamp(6) not null, id bigint generated by default as identity, usuario_id bigint not null unique, semestre varchar(30), telefono varchar(30), expediente_codigo varchar(60) unique, carrera varchar(180) not null, primary key (id));
create table presus.evaluaciones (nota_final float(53), nota_instructor float(53), nota_jurado float(53), peso_instructor float(53) not null, peso_jurado float(53) not null, id bigint generated by default as identity, rubrica_id bigint, solicitud_id bigint unique, resultado varchar(20), comentario_preestablecido TEXT, observaciones TEXT, primary key (id));
create table presus.evaluaciones_criterio (escala integer not null, nota_obtenida float(53) not null, criterio_id bigint not null, evaluador_id bigint not null, jurado_id bigint not null, id bigint generated by default as identity, registrado_en timestamp(6) not null, solicitud_id bigint not null, observacion_auto TEXT, observacion_manual TEXT, observaciones TEXT, primary key (id), unique (evaluador_id, criterio_id));
create table presus.evaluaciones_finales (nota_final float(53), nota_instructor float(53), nota_jurado_promedio float(53), peso_instructor float(53) not null, peso_jurado float(53) not null, resultado_id smallint, fecha_calculo timestamp(6) not null, id bigint generated by default as identity, rubrica_id bigint, solicitud_id bigint not null unique, comentario_preestablecido TEXT, observaciones TEXT, primary key (id));
create table presus.evaluaciones_jurado (nota_jurado float(53) not null, fecha_registro timestamp(6) not null, id bigint generated by default as identity, jurado_id bigint not null, solicitud_id bigint not null, resultado varchar(20), comentario_preestablecido TEXT, observaciones TEXT, primary key (id));
create table presus.evaluadores (peso float(53) not null, tipo_evaluador_id smallint not null, docente_id bigint not null, fecha_asignacion timestamp(6) not null, id bigint generated by default as identity, miembro_tribunal_id bigint, solicitud_id bigint not null, primary key (id));
create table presus.facultades (id integer generated by default as identity, codigo varchar(20) not null unique, nombre varchar(150) not null, primary key (id));
create table presus.historial_cronograma (cronograma_id bigint not null, fecha_anterior timestamp(6) not null, fecha_cambio timestamp(6) not null, fecha_nueva timestamp(6) not null, id bigint generated by default as identity, sala_anterior_id bigint, sala_nueva_id bigint, usuario_id bigint not null, motivo TEXT, primary key (id));
create table presus.historial_estados_solicitud (estado_anterior_id smallint, estado_nuevo_id smallint not null, fecha_cambio timestamp(6) not null, id bigint generated by default as identity, solicitud_id bigint not null, usuario_id bigint not null, comentario TEXT, primary key (id));
create table presus.jornadas (id smallint not null, codigo varchar(20) not null unique, nombre varchar(60) not null, primary key (id));
create table presus.lineas_investigacion (facultad_id integer, id integer generated by default as identity, codigo varchar(20) not null unique, nombre varchar(150) not null, descripcion TEXT, primary key (id));
create table presus.miembros_tribunal (confirmado boolean not null, rol_jurado_id smallint not null, asignado_en timestamp(6) not null, docente_id bigint not null, id bigint generated by default as identity, solicitud_id bigint not null, primary key (id), unique (solicitud_id, docente_id));
create table presus.modalidades_titulacion (id smallint not null, codigo varchar(30) not null unique, nombre varchar(120) not null, primary key (id));
create table presus.notificaciones (leida boolean not null, fecha timestamp(6), id bigint generated by default as identity, usuario_id bigint, mensaje TEXT, primary key (id));
create table presus.periodos_academicos (activo boolean not null, fecha_fin date not null, fecha_inicio date not null, id integer generated by default as identity, codigo varchar(20) not null unique, nombre varchar(100) not null, primary key (id));
create table presus.resultados_evaluacion (id smallint not null, codigo varchar(30) not null unique, nombre varchar(80) not null, primary key (id));
create table presus.roles_jurado (id smallint not null, codigo varchar(30) not null unique, nombre varchar(80) not null, primary key (id));
create table presus.roles_usuario (id smallint not null, codigo varchar(30) not null unique, nombre varchar(80) not null, primary key (id));
create table presus.rubricas (puntaje_maximo float(53) not null, id bigint generated by default as identity, nombre varchar(120) not null, descripcion TEXT, primary key (id));
create table presus.sala (capacidad integer not null, disponible boolean not null, id bigint generated by default as identity, codigo varchar(40) not null unique, nombre varchar(120) not null, primary key (id));
create table presus.solicitud (area_tematica_id integer, convocatoria_id integer not null, estado_id smallint not null, estado varchar(30) not null default 'PENDIENTE', linea_investigacion_id integer, modalidad_titulacion_id smallint not null, actualizado_en timestamp(6) not null, actualizado_por bigint, creado_por bigint, estudiante_id bigint not null, fecha_registro timestamp(6) not null, id bigint generated by default as identity, suspendido_en timestamp(6), titulo_tema varchar(300) not null, motivo_suspension TEXT, observaciones TEXT, primary key (id));
create table presus.tipos_evaluador (id smallint not null, codigo varchar(20) not null unique, nombre varchar(60) not null, primary key (id));
create table presus.tipos_mensaje (id smallint not null, codigo varchar(20) not null unique, nombre varchar(60) not null, primary key (id));
create table presus.tutores (docente_id bigint not null, fecha_asignacion timestamp(6) not null, id bigint generated by default as identity, solicitud_id bigint not null unique, estado_id smallint not null default 1, estado varchar(20) not null, observaciones TEXT, primary key (id));
create table presus.tutoria_fases (numero_fase integer not null, fecha_aprobacion timestamp(6), fecha_inicio timestamp(6) not null, id bigint generated by default as identity, tamano_pdf_bytes bigint, tutor_id bigint not null, estado_id smallint not null default 1, estado varchar(30) not null, sha256_pdf varchar(64), archivo_pdf_estudiante varchar(255), primary key (id));
create table presus.tutoria_mensajes (leido boolean not null, fase_id bigint not null, fecha_envio timestamp(6) not null, id bigint generated by default as identity, remitente_id bigint not null, tipo_mensaje_id smallint not null default 1, tipo varchar(20) not null, contenido TEXT not null, primary key (id));
create table presus.usuarios (activo boolean not null, rol_id smallint not null, creado_en timestamp(6) not null, id bigint generated by default as identity, apellido varchar(255) not null, email varchar(255) not null unique, email_notificaciones varchar(255), nombre varchar(255) not null, password varchar(255) not null, rol varchar(255) not null, telefono varchar(255), primary key (id));
create sequence estados_cronograma_seq start with 1 increment by 50;
create sequence estados_proceso_seq start with 1 increment by 50;
create sequence estados_solicitud_seq start with 1 increment by 50;
create sequence jornadas_seq start with 1 increment by 50;
create sequence modalidades_titulacion_seq start with 1 increment by 50;
create sequence resultados_evaluacion_seq start with 1 increment by 50;
create sequence roles_jurado_seq start with 1 increment by 50;
create sequence roles_usuario_seq start with 1 increment by 50;
create sequence tipos_evaluador_seq start with 1 increment by 50;
create sequence tipos_mensaje_seq start with 1 increment by 50;
